1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUMS: Record<string, number> = {
4	  sword: 100,
5	  amulet: 60,
6	};
7	
8	const COMPONENT_BASE_PREMIUM = 25;
9	const COMPONENT_BLOCK_SIZE = 3;
10	const COMPONENT_BLOCK_PREMIUM = 60;
11	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
12	
13	const FIRST_INSURANCE_SURCHARGE = 0.1;
14	const CURSE_SURCHARGE = 0.5;
15	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
16	const HIGH_ENCHANTMENT_THRESHOLD = 5;
17	const LOYALTY_DISCOUNT = 0.2;
18	const LOYALTY_YEARS_THRESHOLD = 2;
19	const FOLLOWUP_CONTRACT_DISCOUNT = 0.15;
20	
21	const INSURANCE_VALUES: Record<string, number> = {
22	  sword: 1000,
23	  rune: 250,
24	  moonstone: 250,
25	};
26	
27	const DEDUCTIBLE = 100;
28	const CAP_MULTIPLIER = 2;
29	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
30	const HALF_REIMBURSEMENT = 0.5;
31	
32	interface Item {
33	  type: string;
34	  cursed?: boolean;
35	  enchantment?: number;
36	}
37	
38	interface QuoteStep {
39	  op: "quote";
40	  items: Item[];
41	}
42	
43	interface Damage {
44	  itemType: string;
45	  amount: number;
46	}
47	
48	interface ClaimStep {
49	  op: "claim";
50	  policy: number;
51	  incident: { cause: string; damages: Damage[] };
52	}
53	
54	type Step = QuoteStep | ClaimStep;
55	
56	interface Customer {
57	  yearsWithMHPCO: number;
58	}
59	
60	interface Scenario {
61	  customer: Customer;
62	  steps: Step[];
63	}
64	
65	interface QuoteResult {
66	  premium: number;
67	}
68	
69	interface ClaimResult {
70	  payout: number;
71	  remainingCap: number;
72	}
73	
74	type StepResult = QuoteResult | ClaimResult;
75	
76	interface ScenarioResult {
77	  results: StepResult[];
78	}
79	
80	const componentGroupBase = (count: number): number =>
81	  count === COMPONENT_BLOCK_SIZE
82	    ? COMPONENT_BLOCK_PREMIUM
83	    : count * COMPONENT_BASE_PREMIUM;
84	
85	const countByType = (items: Item[]): Map<string, number> => {
86	  const counts = new Map<string, number>();
87	  for (const item of items) {
88	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
89	  }
90	  return counts;
91	};
92	
93	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
94	
95	const isHighEnchantment = (item: Item): boolean =>
96	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
97	
98	interface PricedUnit {
99	  base: number;
100	  surcharges: number[];
101	}
102	
103	const mainItemUnit = (item: Item): PricedUnit => {
104	  const base = BASE_PREMIUMS[item.type];
105	  const surcharges: number[] = [];
106	  if (item.cursed) surcharges.push(base * CURSE_SURCHARGE);
107	  if (isHighEnchantment(item)) surcharges.push(base * HIGH_ENCHANTMENT_SURCHARGE);
108	  return { base, surcharges };
109	};
110	
111	const componentUnit = (count: number): PricedUnit => ({
112	  base: componentGroupBase(count),
113	  surcharges: [],
114	});
115	
116	const pricedUnits = (items: Item[]): PricedUnit[] => {
117	  const mainUnits = items.filter((item) => !isComponent(item)).map(mainItemUnit);
118	
119	  const components = items.filter(isComponent);
120	  const componentUnits = [...countByType(components).values()].map(componentUnit);
121	
122	  return [...mainUnits, ...componentUnits];
123	};
124	
125	const unitTotal = (unit: PricedUnit): number =>
126	  unit.base +
127	  unit.base * FIRST_INSURANCE_SURCHARGE +
128	  unit.surcharges.reduce((sum, surcharge) => sum + surcharge, 0);
129	
130	// Policy-level discount fractions applied to the policy base (sum of unit bases).
131	// Each entry that applies contributes its fraction; new modifiers (e.g. follow-up
132	// contract discount) can be added here without touching per-item pricing.
133	const policyBaseDiscountFractions = (customer: Customer, isFollowUp: boolean): number[] => {
134	  const fractions: number[] = [];
135	  if (customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD) fractions.push(LOYALTY_DISCOUNT);
136	  if (isFollowUp) fractions.push(FOLLOWUP_CONTRACT_DISCOUNT);
137	  return fractions;
138	};
139	
140	const quotePremium = (items: Item[], customer: Customer, isFollowUp: boolean): number => {
141	  const units = pricedUnits(items);
142	  const itemsTotal = units.reduce((sum, unit) => sum + unitTotal(unit), 0);
143	  const policyBase = units.reduce((sum, unit) => sum + unit.base, 0);
144	  const policyDiscount = policyBaseDiscountFractions(customer, isFollowUp).reduce(
145	    (sum, fraction) => sum + policyBase * fraction,
146	    0,
147	  );
148	  return Math.ceil(itemsTotal - policyDiscount + PROCESSING_FEE);
149	};
150	
151	interface Policy {
152	  items: Item[];
153	  cap: number;
154	}
155	
156	const createPolicy = (items: Item[]): Policy => {
157	  const insuranceSum = items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
158	  return { items, cap: insuranceSum * CAP_MULTIPLIER };
159	};
160	
161	const reimbursedAmount = (item: Item | undefined, amount: number): number =>
162	  (item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
163	    ? amount * HALF_REIMBURSEMENT
164	    : amount;
165	
166	const damagePayout = (policy: Policy, damage: Damage): number => {
167	  const item = policy.items.find((candidate) => candidate.type === damage.itemType);
168	  return reimbursedAmount(item, damage.amount) - DEDUCTIBLE;
169	};
170	
171	const processClaim = (policy: Policy, damages: Damage[]): ClaimResult => {
172	  const payout = damages.reduce((sum, damage) => sum + damagePayout(policy, damage), 0);
173	  return { payout, remainingCap: policy.cap - payout };
174	};
175	
176	export const runScenario = (scenario: Scenario): ScenarioResult => {
177	  const policies: Policy[] = [];
178	  let quoteCount = 0;
179	
180	  const handleQuote = (step: QuoteStep): QuoteResult => {
181	    const isFollowUp = quoteCount > 0;
182	    quoteCount += 1;
183	    policies.push(createPolicy(step.items));
184	    return { premium: quotePremium(step.items, scenario.customer, isFollowUp) };
185	  };
186	
187	  const handleClaim = (step: ClaimStep): ClaimResult =>
188	    processClaim(policies[step.policy], step.incident.damages);
189	
190	  const results = scenario.steps.map((step): StepResult =>
191	    step.op === "quote" ? handleQuote(step) : handleClaim(step),
192	  );
193	  return { results };
194	};
